q=A.v(j,A.bR0(q,B.ad,3,!1,B.ad,B.B_,j,A.a([A.ps(B.aog,k.ip(e,"Wer ist Kkaebi?","Who is Kkaebi?","\u0915\u0948\u092c\u0940 \u0915\u094c\u0928 \u0939\u0948?","\u30c8\u30c3\u30b1\u30d3\u3068\u306f\uff1f","\uae68\ube44\ub294 \ub204\uad6c?","\u5409\u9b3c\u662f\u8c01\uff1f")),A.ps(B.amb,k.ip(e,"DOK-KEY Anleitung","App Guide",h,"DOK-KEY \u8aac\u660e\u66f8","DOK-KEY \ub3c4\uc6c0\ub9d0","\u7cfb\u7edf\u8bf4\u660e\u4e66"))],s),B.w7),B.m,B.mW,j,j,j,j,j,j,j,j,j,j)
p=k.d
o=k.ip(e,"Herkunft & Entstehung von Kkaebi","Origin of Kkaebi","\u0915\u0948\u092c\u0940 \u0915\u0940 \u0909\u0924\u094d\u092a\u0924\u094d\u0924\u093f \u0914\u0930 \u091c\u0928\u094d\u092e","\u30c8\u30c3\u30b1\u30d3\u306e\u7531\u6765\u3068\u8a95\u751f","\uae68\ube44\uc758 \uc720\ub798\uc640 \ud0c4\uc0dd","\u5409\u9b3c\u7684\u6e0a\u6e90\u4e0e\u8bde\u751f")
